function httpFailure(response) {
 if(response.error!==undefined) {
   const message=typeof response.error==='string'?response.error:JSON.stringify(response.error??'');
   return /invalid_grant|invalid_client|unauthorized_client|invalid_scope|private key|privateKey|asymmetric|PEM|JWT/i.test(message)?failure('auth'):failure('unavailable',true);
 }
 const status=response.statusCode;
