function existingEvent(response,request) {
 const error=httpFailure(response);
 if(error)return error;
 const event=response.body;
 const metadata=event?.extendedProperties?.private;
 if(event?.id!==request.eventId || event.status==='cancelled' || metadata?.zenvolyx!=='true' || metadata?.clientId!==request.clientId || metadata?.leadId!==request.lead.id || Date.parse(event.start?.dateTime)!==Date.parse(request.slot.start)||Date.parse(event.end?.dateTime)!==Date.parse(request.slot.end))return failure('event_conflict');
 return {ok:true,eventId:event.id};
}
